// Generated by `nix run .#update-theme` from arkui/theme.toml: edit that, then run it.
//
// The theme's numbers, Foundation alone, so Linux builds them: the colours
// every app shares, each app's accent and the derived squares, as
// `0xRRGGBB` for each side. ArkUI's `Color` tokens are made of these.

/// A colour for each side, as `0xRRGGBB`.
public struct Sides: Equatable, Sendable {
    public let light: UInt32
    public let dark: UInt32

    public init(light: UInt32, dark: UInt32) {
        self.light = light
        self.dark = dark
    }

    /// The colour for one side.
    public func of(dark: Bool) -> UInt32 { dark ? self.dark : light }
}

/// The colours every app shares: the neutrals and the signals.
public enum Tokens {
    /// The page.
    public static let background = Sides(light: 0xFFFFFF, dark: 0x1C1C1C)
    /// A plane over the page: a sheet, a card, a bar.
    public static let surface = Sides(light: 0xFFFFFF, dark: 0x1C1C1C)
    /// The faintest step a container takes off the page.
    public static let containerLowest = Sides(light: 0xFFFFFF, dark: 0x161616)
    /// A container one step off the page.
    public static let containerLow = Sides(light: 0xF7F7F7, dark: 0x212121)
    /// A container: a field, a grouped list's rows.
    public static let container = Sides(light: 0xF2F2F2, dark: 0x262626)
    /// A container a step further: a chip, a track.
    public static let containerHigh = Sides(light: 0xECECEC, dark: 0x2E2E2E)
    /// The furthest step: a pressed row, a meter's track.
    public static let containerHighest = Sides(light: 0xE5E5E5, dark: 0x363636)
    /// The fill of a glass chip, menu and sheet.
    public static let glass = Sides(light: 0xFFFFFF, dark: 0x3A3A3A)
    /// The edge of a control: a field, an unchecked box.
    public static let outline = Sides(light: 0x878787, dark: 0x7A7A7A)
    /// A divider, and a cover's edge.
    public static let hairline = Sides(light: 0xE3E3E3, dark: 0x333333)
    /// Text.
    public static let ink = Sides(light: 0x1C1C1C, dark: 0xE8E8E8)
    /// Secondary text: a subtitle, a count, a caption.
    public static let quiet = Sides(light: 0x5E5E5E, dark: 0xB0B0B0)
    /// What cannot be pressed.
    public static let disabled = Sides(light: 0x9E9E9E, dark: 0x6E6E6E)
    /// What dims the page under a dialog.
    public static let scrim = Sides(light: 0x000000, dark: 0x000000)
    /// A snackbar: the other side's surface.
    public static let inverseSurface = Sides(light: 0x2E2E2E, dark: 0xE8E8E8)
    /// Text on the inverse surface.
    public static let inverseInk = Sides(light: 0xF2F2F2, dark: 0x262626)
    /// Wrong: an error, an overspent amount.
    public static let error = Sides(light: 0xB3261E, dark: 0xF2B8B5)
    /// What is written on the error colour.
    public static let onError = Sides(light: 0xFFFFFF, dark: 0x601410)
    /// A quiet container for an error.
    public static let errorContainer = Sides(light: 0xF9DEDC, dark: 0x5A1E1A)
    /// What is written on that.
    public static let onErrorContainer = Sides(light: 0x410E0B, dark: 0xF9DEDC)
    /// Worth a look: an amount short of its target.
    public static let caution = Sides(light: 0x8A5100, dark: 0xFFB86E)
    /// What is written on the caution colour.
    public static let onCaution = Sides(light: 0xFFFFFF, dark: 0x3D2200)
    /// A quiet container for a caution.
    public static let cautionContainer = Sides(light: 0xFFE3C4, dark: 0x5A3A12)
    /// What is written on that.
    public static let onCautionContainer = Sides(light: 0x3A1F00, dark: 0xFFDCBC)
    /// Good: money with a job, a goal met.
    public static let positive = Sides(light: 0x186A3B, dark: 0x5FCF8E)
    /// How much of the cover shows through behind the full player.
    public static func washOpacity(dark: Bool) -> Double { dark ? 0.25 : 0.25 }
}

/// An app's accent: the one colour that is the app's own, and the squares it draws.
public struct AccentSet: Equatable, Sendable {
    /// The accent: a filled button, a slider, a selected tab.
    public let accent: Sides
    /// What is written on the accent.
    public let onAccent: Sides
    /// The accent as text: a link, the row playing.
    public let accentText: Sides
    /// A quiet container in the accent.
    public let accentContainer: Sides
    /// What is written on that.
    public let onAccentContainer: Sides
    /// The derived squares it draws.
    public let squares: Squares

    public static let gold = AccentSet(
        accent: Sides(light: 0x7A5B10, dark: 0xE9BB45),
        onAccent: Sides(light: 0xFFFFFF, dark: 0x1C1C1C),
